package engine

import "testing"

func TestViewTransition(t *testing.T) {
	tab := platformTab(t)
	runJSCases(t, tab, []jsCase{
		{"runs the callback after the call returns", `const log = []; const vt = document.startViewTransition(() => { log.push('cb'); }); log.push('sync'); await vt.finished; return [log, vt instanceof ViewTransition, String(vt)];`, `[["sync","cb"],true,"[object ViewTransition]"]`},
		{"promises settle in order", `const log = []; const vt = document.startViewTransition(async () => { await 0; log.push('cb'); }); vt.updateCallbackDone.then(() => log.push('done')); vt.ready.then(() => log.push('ready')); await vt.finished; log.push('finished'); return log;`, `["cb","done","ready","finished"]`},
		{"callback sees DOM updates", `const vt = document.startViewTransition(() => { document.body.setAttribute('data-vt', '1'); }); await vt.updateCallbackDone; return document.body.getAttribute('data-vt');`, `"1"`},
		{"no callback", `const vt = document.startViewTransition(); await vt.finished; return 'ok';`, `"ok"`},
		{"callback throwing rejects all three", `const vt = document.startViewTransition(() => { throw new RangeError('boom'); }); const out = []; for (const p of [vt.updateCallbackDone, vt.ready, vt.finished]) { try { await p; out.push('ok'); } catch (e) { out.push(e.message); } } return out;`, `["boom","boom","boom"]`},
		{"callback rejecting", `const vt = document.startViewTransition(() => Promise.reject(new Error('no'))); try { await vt.finished; } catch (e) { return e.message; }`, `"no"`},
		{"skipTransition", `const log = []; const vt = document.startViewTransition(() => { log.push('cb'); }); vt.skipTransition(); let r; try { await vt.ready; } catch (e) { r = e.name; } await vt.finished; return [r, log];`, `["AbortError",["cb"]]`},
		{"a new transition skips the previous one", `const a = document.startViewTransition(() => { }); const b = document.startViewTransition(() => { }); let r; try { await a.ready; } catch (e) { r = e.name; } await b.finished; await a.finished; return [r, document.activeViewTransition];`, `["AbortError",null]`},
		{"options form with types", `const vt = document.startViewTransition({ update: () => { }, types: ['slide', 'back'] }); const t = [...vt.types]; vt.types.add('extra'); await vt.finished; return [t, vt.types.has('extra'), vt.types.size, typeof ViewTransitionTypeSet];`, `[["slide","back"],true,3,"function"]`},
		{"activeViewTransition", `const vt = document.startViewTransition(() => { }); const same = document.activeViewTransition === vt; await vt.finished; return [same, document.activeViewTransition];`, `[true,null]`},
		{"invalid arguments", `const out = []; for (const a of [5, { update: 5 }]) { try { document.startViewTransition(a); out.push('ok'); } catch (e) { out.push(e.name); } } return out;`, `["TypeError","TypeError"]`},
		{"illegal constructor", `try { new ViewTransition(); } catch (e) { return e.name; }`, `"TypeError"`},
	})
}

func TestNavigationAPI(t *testing.T) {
	tab := platformTab(t)
	runJSCases(t, tab, []jsCase{
		{"initial state", `navigation.addEventListener('navigate', e => { if (e.canIntercept && !e.hashChange && !e.defaultPrevented) e.intercept(); }); const n = navigation; const e = n.currentEntry; return [n.entries().length, e.url === location.href, e.index, e.sameDocument, typeof e.key, typeof e.id, n.canGoBack, n.canGoForward, n.transition, n.activation.entry === e, n.activation.navigationType, String(n)];`, `[1,true,0,true,"string","string",false,false,null,true,"push","[object Navigation]"]`},
		{"pushState adds entries and fires events", `const ev = []; navigation.oncurrententrychange = e => ev.push(['cec', e.navigationType, e.from.index]); navigation.addEventListener('navigate', e => ev.push(['nav', e.navigationType, e.cancelable, e.canIntercept, e.destination.sameDocument])); history.pushState({ a: 1 }, '', '/static?one'); history.pushState(null, '', '/static?two'); const es = navigation.entries(); navigation.oncurrententrychange = null; return [ev, es.length, es.map(e => e.index), navigation.currentEntry.url.endsWith('?two'), navigation.canGoBack, history.length];`, `[[["nav","push",false,true,true],["cec","push",0],["nav","push",false,true,true],["cec","push",1]],3,[0,1,2],true,true,3]`},
		{"back and forward by navigation", `const r = navigation.back(); const c = await r.committed; const f = await r.finished; const at = navigation.currentEntry.url; const e1 = navigation.currentEntry.index; await navigation.forward().finished; return [c === f, at.endsWith('?one'), e1, navigation.currentEntry.url.endsWith('?two'), history.state];`, `[true,true,1,true,null]`},
		{"traverse restores history.state", `history.pushState({ s: 'x' }, '', '/static?three'); const back = await navigation.back().finished; const st = history.state; await navigation.forward().finished; return [st, history.state, location.search];`, `[null,{"s":"x"},"?three"]`},
		{"history.back is routed through traverse", `const types = []; const l = e => types.push(e.navigationType); navigation.addEventListener('navigate', l); const popped = new Promise(r => addEventListener('popstate', r, { once: true })); history.back(); await popped; navigation.removeEventListener('navigate', l); await navigation.forward().finished; return [types, navigation.currentEntry.index];`, `[["traverse"],3]`},
		{"back at the start throws", `const n2 = navigation.entries().length; let a; try { navigation.traverseTo('nope'); } catch (e) { a = e.name; } await navigation.traverseTo(navigation.entries()[0].key).finished; let b; try { navigation.back(); } catch (e) { b = e.name; } await navigation.traverseTo(navigation.entries()[n2 - 1].key).finished; return [a, b, navigation.currentEntry.index === n2 - 1];`, `["InvalidStateError","InvalidStateError",true]`},
		{"push after back disposes forward entries", `await navigation.back().finished; const old = navigation.entries()[navigation.entries().length - 1]; let disposed = 0; old.ondispose = () => disposed++; history.pushState(null, '', '/static?fresh'); return [disposed, old.index, old.url, navigation.entries().length, navigation.currentEntry.url.endsWith('?fresh')];`, `[1,-1,null,4,true]`},
		{"replaceState", `const before = navigation.currentEntry; const ev = []; navigation.oncurrententrychange = e => ev.push([e.navigationType, e.from === before, e.from.index]); history.replaceState({ r: 1 }, '', '/static?replaced'); navigation.oncurrententrychange = null; return [ev, navigation.entries().length, navigation.currentEntry.key === before.key, navigation.currentEntry.id === before.id, navigation.currentEntry.url.endsWith('?replaced')];`, `[[["replace",true,-1]],4,true,false,true]`},
		{"navigate with state and history option", `const n = navigation.entries().length; const r = navigation.navigate('/static?withstate', { state: { deep: { x: [1, 2] } }, info: 'i' }); const e = await r.finished; const eu = e.url; const st = e.getState(); st.deep.x.push(3); const again = e.getState(); await navigation.navigate('/static?rep', { history: 'replace' }).finished; return [eu.endsWith('withstate'), again, navigation.entries().length === n + 1, navigation.currentEntry.url.endsWith('?rep'), navigation.currentEntry.getState()];`, `[true,{"deep":{"x":[1,2]}},true,true,null]`},
		{"navigate event details and info", `let seen; navigation.addEventListener('navigate', e => { seen = [e.navigationType, e.destination.url.endsWith('?dest'), e.destination.getState(), e.info, e.userInitiated, e.hashChange, e.signal instanceof AbortSignal, e.formData, e.downloadRequest, e instanceof NavigateEvent, e.destination.index, e.destination.sameDocument]; e.intercept(); }, { once: true }); await navigation.navigate('/static?dest', { state: 'st', info: { k: 1 } }).finished; return seen;`, `["push",true,"st",{"k":1},false,false,true,null,null,true,-1,false]`},
		{"intercept runs the handler without a page load", `const log = []; let marker = 'same-page'; window.__mk = marker; navigation.addEventListener('navigate', e => { e.intercept({ handler: async () => { log.push('handler:' + navigation.transition.navigationType); await new Promise(r => setTimeout(r, 5)); log.push('handled'); } }); }, { once: true }); navigation.addEventListener('navigatesuccess', () => log.push('success'), { once: true }); const r = navigation.navigate('/static?intercepted'); const during = navigation.transition; const c = await r.committed; log.push('committed:' + location.search); await r.finished; return [log, window.__mk, during !== null, navigation.transition, c.url.endsWith('?intercepted'), during.from.url.endsWith('?dest')];`, `[["handler:push","committed:?intercepted","handled","success"],"same-page",true,null,true,true]`},
		{"handler rejection fires navigateerror", `navigation.addEventListener('navigate', e => e.intercept({ handler: () => Promise.reject(new RangeError('bad')) }), { once: true }); let errEv; navigation.addEventListener('navigateerror', e => errEv = e, { once: true }); const r = navigation.navigate('/static?fail'); let rej; try { await r.finished; } catch (e) { rej = e.name; } await r.committed; return [rej, errEv && errEv.error.name, errEv instanceof ErrorEvent, navigation.transition];`, `["RangeError","RangeError",true,null]`},
		{"preventDefault cancels the navigation", `navigation.addEventListener('navigate', e => e.preventDefault(), { once: true }); const before = location.href; const r = navigation.navigate('/static?blocked'); const out = []; for (const p of [r.committed, r.finished]) { try { await p; out.push('ok'); } catch (e) { out.push(e.name); } } return [out, location.href === before];`, `[["AbortError","AbortError"],true]`},
		{"a newer navigation aborts the ongoing one", `let sig; navigation.addEventListener('navigate', e => { sig = e.signal; e.intercept({ handler: () => new Promise(r => setTimeout(r, 50)) }); }, { once: true }); const first = navigation.navigate('/static?slow'); await first.committed; const second = navigation.navigate('/static?quick', { history: 'replace' }); let e1; try { await first.finished; } catch (e) { e1 = e.name; } await second.finished; return [e1, sig.aborted, location.search];`, `["AbortError",true,"?quick"]`},
		{"canIntercept is false across origins", `let seen; navigation.addEventListener('navigate', e => { seen = [e.canIntercept, (() => { try { e.intercept(); return 'ok'; } catch (x) { return x.name; } })()]; e.preventDefault(); }, { once: true }); try { await navigation.navigate('https://other.example/page').finished; } catch (e) { } return seen;`, `[false,"SecurityError"]`},
		{"intercept outside dispatch", `let ev; navigation.addEventListener('navigate', e => { ev = e; e.intercept(); }, { once: true }); await navigation.navigate('/static?later').finished; try { ev.intercept(); } catch (e) { return e.name; }`, `"InvalidStateError"`},
		{"fragment navigation", `const seen = []; navigation.addEventListener('navigate', e => seen.push([e.hashChange, e.destination.sameDocument]), { once: true }); const hc = new Promise(r => addEventListener('hashchange', r, { once: true })); const r = navigation.navigate('#frag'); await r.finished; await hc; return [seen, location.hash, navigation.currentEntry.url.endsWith('#frag')];`, `[[[true,true]],"#frag",true]`},
		{"location.hash writes an entry", `const n = navigation.entries().length; const cec = new Promise(r => navigation.addEventListener('currententrychange', r, { once: true })); location.hash = '#viahash'; const e = await cec; return [e.navigationType, navigation.entries().length === n + 1, e instanceof NavigationCurrentEntryChangeEvent];`, `["push",true,true]`},
		{"updateCurrentEntry", `const e0 = navigation.currentEntry; const got = new Promise(r => navigation.addEventListener('currententrychange', r, { once: true })); navigation.updateCurrentEntry({ state: { u: 1 } }); const ev = await got; let bad; try { navigation.updateCurrentEntry({}); } catch (e) { bad = e.name; } return [ev.navigationType, ev.from === e0, e0.getState(), bad];`, `[null,true,{"u":1},"TypeError"]`},
		{"reload with intercept", `let n = 0; navigation.addEventListener('navigate', e => { n++; e.intercept({ handler: async () => { } }); }, { once: true }); const len = navigation.entries().length; const mk = window.__mk; const t = []; await navigation.reload({ info: 1 }).finished; return [n, navigation.entries().length === len, window.__mk === mk];`, `[1,true,true]`},
		{"invalid arguments", `const out = []; for (const f of [() => navigation.navigate('http://[bad'), () => navigation.navigate('/x', { history: 'sideways' }), () => navigation.navigate('/x', { state: () => 1 }), () => navigation.navigate(), () => new NavigateEvent('navigate')]) { try { f(); out.push('ok'); } catch (e) { out.push(e.name); } } return out;`, `["SyntaxError","TypeError","DataCloneError","TypeError","TypeError"]`},
		{"classes", `return [typeof NavigationHistoryEntry, typeof NavigationDestination, typeof NavigationTransition, typeof NavigationActivation, navigation.currentEntry instanceof EventTarget, navigation instanceof EventTarget, Object.prototype.toString.call(navigation.currentEntry)];`, `["function","function","function","function",true,true,"[object NavigationHistoryEntry]"]`},
	})
}

func TestElementInternals(t *testing.T) {
	tab := platformTab(t)
	setup := `
if (!customElements.get('x-field')) customElements.define('x-field', class extends HTMLElement { static formAssociated = true; constructor() { super(); this.i = this.attachInternals(); } formResetCallback() { this.i.setFormValue(''); this.resets = (this.resets || 0) + 1; } });
if (!customElements.get('x-plain')) customElements.define('x-plain', class extends HTMLElement { constructor() { super(); this.i = this.attachInternals(); } });
document.body.innerHTML = '<form id="f"><label id="l" for="a">Name</label><x-field id="a" name="who"></x-field><x-field name="zip" id="z"></x-field></form><x-plain id="p"></x-plain>';
const f = document.getElementById('f'), a = document.getElementById('a'), z = document.getElementById('z'), p = document.getElementById('p');
`
	runJSCases(t, tab, []jsCase{
		{"attachInternals rejects non custom elements", setup + `const out = []; for (const el of [document.createElement('div'), document.createElement('span'), document.createElement('unknown-el')]) { try { el.attachInternals(); out.push('ok'); } catch (e) { out.push(e.name); } } return out;`, `["NotSupportedError","NotSupportedError","ok"]`},
		{"attach twice", setup + `try { a.attachInternals(); } catch (e) { return e.name; }`, `"NotSupportedError"`},
		{"basic shape", setup + `return [a.i instanceof ElementInternals, String(a.i), a.i.form === f, p.i.form, a.i.shadowRoot, typeof a.i.states.add, a.i.states instanceof Set, String(a.i.states)];`, `[true,"[object ElementInternals]",true,null,null,"function",true,"[object CustomStateSet]"]`},
		{"setFormValue feeds FormData", setup + `a.i.setFormValue('Ada'); z.i.setFormValue(new File(['x'], 'z.txt')); const fd = new FormData(f); return [fd.get('who'), fd.get('zip').name, [...fd.keys()]];`, `["Ada","z.txt",["who","zip"]]`},
		{"setFormValue null and disabled", setup + `a.i.setFormValue(null); z.i.setFormValue('v'); z.setAttribute('disabled', ''); const fd = new FormData(f); return [fd.has('who'), fd.has('zip')];`, `[false,false]`},
		{"setFormValue with a FormData entry list", setup + `const inner = new FormData(); inner.append('a', '1'); inner.append('b', '2'); a.i.setFormValue(inner); const fd = new FormData(f); return [fd.get('a'), fd.get('b')];`, `["1","2"]`},
		{"setFormValue type check", setup + `try { a.i.setFormValue(5); } catch (e) { return e.name; }`, `"TypeError"`},
		{"non form-associated elements reject form APIs", setup + `const out = []; for (const fn of [() => p.i.setFormValue('x'), () => p.i.setValidity({}), () => p.i.validity, () => p.i.labels, () => p.i.willValidate, () => p.i.checkValidity()]) { try { fn(); out.push('ok'); } catch (e) { out.push(e.name); } } return out;`, `["NotSupportedError","NotSupportedError","NotSupportedError","NotSupportedError","NotSupportedError","NotSupportedError"]`},
		{"validity defaults", setup + `const v = a.i.validity; return [v.valid, v.valueMissing, v.customError, a.i.validationMessage, a.i.willValidate, a.i.checkValidity(), v instanceof ValidityState];`, `[true,false,false,"",true,true,true]`},
		{"setValidity flags and message", setup + `a.i.setValidity({ valueMissing: true, customError: true }, 'Fill this in'); const v = a.i.validity; const r = [v.valid, v.valueMissing, v.customError, v.tooLong, a.i.validationMessage]; a.i.setValidity({}); return [r, a.i.validity.valid, a.i.validationMessage];`, `[[false,true,true,false,"Fill this in"],true,""]`},
		{"setValidity needs a message", setup + `try { a.i.setValidity({ valueMissing: true }); } catch (e) { return e.name; }`, `"TypeError"`},
		{"setValidity anchor must be inside", setup + `const b = document.createElement('b'); a.appendChild(b); a.i.setValidity({ customError: true }, 'm', b); try { a.i.setValidity({ customError: true }, 'm', p); } catch (e) { return e.name; }`, `"NotFoundError"`},
		{"checkValidity fires invalid", setup + `let n = 0; a.addEventListener('invalid', () => n++); a.i.setValidity({ patternMismatch: true }, 'bad'); const r = [a.i.checkValidity(), a.i.reportValidity(), n]; a.setAttribute('disabled', ''); return [r, a.i.checkValidity(), a.i.willValidate, n];`, `[[false,false,2],true,false,2]`},
		{"labels", setup + `return [a.i.labels.length, a.i.labels[0].id, z.i.labels.length];`, `[1,"l",0]`},
		{"form owner via form attribute", setup + `const other = document.createElement('form'); other.id = 'o'; document.body.appendChild(other); p.remove(); const x = document.createElement('x-field'); x.setAttribute('form', 'o'); document.body.appendChild(x); return [x.i.form === other, x.i.form === f];`, `[true,false]`},
		{"states", setup + `const s = a.i.states; s.add('checked'); s.add('busy'); const r = [s.has('checked'), s.size, [...s]]; s.delete('busy'); s.clear(); return [r, s.size];`, `[[true,2,["checked","busy"]],0]`},
		{"aria defaults", setup + `const i = a.i; const before = [i.ariaLabel, i.role]; i.ariaLabel = 'Name'; i.role = 'textbox'; i.ariaChecked = 'true'; const r = [before, i.ariaLabel, i.role, i.ariaChecked, a.getAttribute('role'), a.hasAttribute('aria-label')]; i.ariaLabel = null; return [r, i.ariaLabel];`, `[[[null,null],"Name","textbox","true",null,false],null]`},
		{"form.reset calls formResetCallback", setup + `a.i.setFormValue('typed'); f.reset(); return [a.resets, z.resets === 1, new FormData(f).get('who')];`, `[1,true,""]`},
		{"illegal constructors", setup + `const out = []; for (const C of [ElementInternals, CustomStateSet, ValidityState]) { try { new C(); out.push('ok'); } catch (e) { out.push(e.name); } } return out;`, `["TypeError","TypeError","TypeError"]`},
	})
}

func TestCSSHighlightAndProperties(t *testing.T) {
	tab := platformTab(t)
	pre := `document.body.innerHTML = '<p id="p">Hello world</p>'; const txt = document.getElementById('p').firstChild; const mk = (a, b) => { const r = new Range(); r.setStart(txt, a); r.setEnd(txt, b); return r; };
`
	runJSCases(t, tab, []jsCase{
		{"registry shape", pre + `return [CSS.highlights instanceof HighlightRegistry, CSS.highlights.size, String(CSS.highlights), CSS.highlights === CSS.highlights];`, `[true,0,"[object HighlightRegistry]",true]`},
		{"set get has delete", pre + `const h = new Highlight(mk(0, 5)); CSS.highlights.set('search', h); const r = [CSS.highlights.get('search') === h, CSS.highlights.has('search'), CSS.highlights.size, CSS.highlights.get('nope')]; const d = CSS.highlights.delete('search'); return [r, d, CSS.highlights.has('search'), CSS.highlights.delete('search')];`, `[[true,true,1,null],true,false,false]`},
		{"registry iteration and chaining", pre + `CSS.highlights.clear(); CSS.highlights.set('a', new Highlight()).set('b', new Highlight()); const keys = [...CSS.highlights.keys()]; const ents = [...CSS.highlights].map(e => e[0]); const seen = []; CSS.highlights.forEach((v, k, m) => seen.push([k, v instanceof Highlight, m === CSS.highlights])); CSS.highlights.clear(); return [keys, ents, seen, CSS.highlights.size];`, `[["a","b"],["a","b"],[["a",true,true],["b",true,true]],0]`},
		{"registry rejects non-highlights", pre + `try { CSS.highlights.set('x', {}); } catch (e) { return e.name; }`, `"TypeError"`},
		{"highlight is a set of ranges", pre + `const r1 = mk(0, 2), r2 = mk(3, 5); const h = new Highlight(r1, r2); h.add(r1); const before = h.size; h.delete(r2); return [before, h.size, h.has(r1), h.has(r2), [...h].length, h.priority, h.type, h.add(r2) === h];`, `[2,1,true,false,1,0,"highlight",true]`},
		{"highlight priority and type", pre + `const h = new Highlight(); h.priority = 5.9; h.type = 'spelling-error'; h.type = 'nonsense'; return [h.priority, h.type];`, `[5,"spelling-error"]`},
		{"highlight accepts StaticRange and Range only", pre + `const h = new Highlight(new StaticRange({ startContainer: txt, startOffset: 0, endContainer: txt, endOffset: 3 })); let bad; try { h.add({}); } catch (e) { bad = e.name; } let bad2; try { new Highlight(5); } catch (e) { bad2 = e.name; } return [h.size, bad, bad2, new Range() instanceof AbstractRange, new StaticRange({ startContainer: txt, startOffset: 0, endContainer: txt, endOffset: 1 }) instanceof AbstractRange];`, `[1,"TypeError","TypeError",true,true]`},
		{"highlight iteration protocols", pre + `const r1 = mk(0, 1); const h = new Highlight(r1); const e = [...h.entries()]; const vals = []; h.forEach((v, k, s) => vals.push([v === r1, k === r1, s === h])); return [e[0][0] === r1, e[0][1] === r1, vals, h[Symbol.iterator] === h.values];`, `[true,true,[[true,true,true]],true]`},

		{"registerProperty basics", `CSS.registerProperty({ name: '--accent', syntax: '<color>', inherits: false, initialValue: 'red' }); const r = CSS.registeredProperty('--accent'); return [r instanceof CSSPropertyRule, r instanceof CSSRule, r.name, r.syntax, r.inherits, r.initialValue, r.cssText, String(r)];`, `[true,true,"--accent","\u003ccolor\u003e",false,"red","@property --accent { syntax: \"\u003ccolor\u003e\"; inherits: false; initial-value: red; }","[object CSSPropertyRule]"]`},
		{"registerProperty universal syntax", `CSS.registerProperty({ name: '--any', inherits: true }); const r = CSS.registeredProperty('--any'); return [r.syntax, r.inherits, r.initialValue];`, `["*",true,null]`},
		{"registerProperty list syntaxes", `CSS.registerProperty({ name: '--len', syntax: '<length> | auto', inherits: false, initialValue: '0' }); CSS.registerProperty({ name: '--nums', syntax: '<number>+', inherits: false, initialValue: '1 2 3' }); CSS.registerProperty({ name: '--cols', syntax: '<color>#', inherits: false, initialValue: 'red, blue' }); return CSS.registeredProperty('--nums').initialValue;`, `"1 2 3"`},
		{"registerProperty errors", `const out = []; const tryIt = d => { try { CSS.registerProperty(d); out.push('ok'); } catch (e) { out.push(e.name); } };
tryIt({ name: 'plain', inherits: false }); tryIt({ name: '--e1', syntax: '<length>', inherits: false }); tryIt({ name: '--e2', syntax: '<length>', inherits: false, initialValue: 'red' }); tryIt({ name: '--e3', syntax: 'nonsense', inherits: false, initialValue: '1' }); tryIt({ name: '--accent', inherits: false }); tryIt({ name: '--e4' }); tryIt({ inherits: false }); tryIt(null); tryIt({ name: '--e5', syntax: '<number>', inherits: false, initialValue: '1px' }); return out;`, `["SyntaxError","TypeError","SyntaxError","SyntaxError","InvalidModificationError","TypeError","TypeError","TypeError","SyntaxError"]`},
		{"CSSPropertyRule is not constructible", `try { new CSSPropertyRule(); } catch (e) { return [e.name, CSSRule.STYLE_RULE, typeof CSSRule]; }`, `["TypeError",1,"function"]`},
		{"ContentVisibilityAutoStateChangeEvent", `const e = new ContentVisibilityAutoStateChangeEvent('contentvisibilityautostatechange', { skipped: true }); const d = new ContentVisibilityAutoStateChangeEvent('x'); let got; document.body.addEventListener('contentvisibilityautostatechange', ev => got = ev.skipped); document.body.dispatchEvent(e); return [e.skipped, d.skipped, e instanceof Event, got, e.type, String(e)];`, `[true,false,true,true,"contentvisibilityautostatechange","[object ContentVisibilityAutoStateChangeEvent]"]`},
	})
}
